insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x4-c1$qa$, $qa$pemweb-x4$qa$, $qa$checkpoint$qa$, $qa$Apa perbedaan colspan dan rowspan pada tabel HTML?$qa$, $qa$["colspan menggabungkan baris, rowspan menggabungkan kolom", "colspan menggabungkan kolom, rowspan menggabungkan baris", "Keduanya menggabungkan baris", "Keduanya hanya untuk styling"]$qa$::jsonb, 1, $qa$colspan="2" menggabungkan 2 kolom, rowspan="2" menggabungkan 2 baris.$qa$, 1) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x4-c2$qa$, $qa$pemweb-x4$qa$, $qa$checkpoint$qa$, $qa$Formulir login sebaiknya memakai method POST karena...$qa$, $qa$["Data tampil di URL sehingga mudah di-bookmark", "Data dikirim di body request sehingga tidak terlihat di URL", "POST selalu lebih cepat dari GET", "GET tidak bisa dipakai untuk formulir"]$qa$::jsonb, 1, $qa$POST menaruh data di body request (tidak terlihat di URL), cocok untuk data sensitif seperti login.$qa$, 2) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x4-c3$qa$, $qa$pemweb-x4$qa$, $qa$checkpoint$qa$, $qa$Pada Flexbox dengan flex-direction: row, justify-content mengatur perataan sepanjang...$qa$, $qa$["Cross axis (vertikal)", "Main axis (horizontal)", "Sumbu Z (kedalaman)", "Diagonal container"]$qa$::jsonb, 1, $qa$justify-content bekerja sepanjang main axis — horizontal saat direction row; align-items untuk cross axis.$qa$, 3) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x4-b1$qa$, $qa$pemweb-x4$qa$, $qa$battle$qa$, $qa$Atribut colspan="2" pada sel tabel berfungsi untuk...$qa$, $qa$["Menggabungkan 2 baris menjadi satu", "Menggabungkan 2 kolom menjadi satu", "Membuat 2 tabel baru", "Menghapus 2 kolom"]$qa$::jsonb, 1, $qa$colspan (column span) menggabungkan sel secara horizontal melintasi beberapa kolom.$qa$, 1) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x4-b2$qa$, $qa$pemweb-x4$qa$, $qa$battle$qa$, $qa$Untuk mengirim data login yang bersifat sensitif, method form yang tepat adalah POST karena...$qa$, $qa$["Datanya tampil di URL sehingga mudah dibookmark", "Data dikirim di body request dan tidak terlihat di URL", "POST lebih cepat dari GET", "GET tidak bisa mengirim data sama sekali"]$qa$::jsonb, 1, $qa$POST menyembunyikan data di body request, sedangkan GET menempelkannya di URL sebagai query string.$qa$, 2) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x4-b3$qa$, $qa$pemweb-x4$qa$, $qa$battle$qa$, $qa$Pada container dengan flex-direction: row, properti justify-content mengatur perataan ke arah...$qa$, $qa$["Vertikal (atas-bawah)", "Horizontal (kiri-kanan)", "Diagonal", "Tidak mengatur arah sama sekali"]$qa$::jsonb, 1, $qa$justify-content bekerja pada main axis; bila direction row, main axis-nya horizontal.$qa$, 3) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x4-b4$qa$, $qa$pemweb-x4$qa$, $qa$battle$qa$, $qa$Arti dari grid-template-columns: 1fr 2fr; adalah...$qa$, $qa$["Satu kolom selebar 12fr", "Dua kolom dengan lebar rasio 1 banding 2", "Dua belas kolom sama besar", "Satu baris dua kolom dengan satuan piksel"]$qa$::jsonb, 1, $qa$Satuan fr membagi ruang tersisa secara proporsional, jadi kolom kedua dua kali kolom pertama.$qa$, 4) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x4-b5$qa$, $qa$pemweb-x4$qa$, $qa$battle$qa$, $qa$Perbedaan radio button dan checkbox pada form adalah...$qa$, $qa$["Keduanya hanya boleh dipilih satu", "Radio untuk memilih satu opsi, checkbox boleh memilih banyak opsi", "Checkbox hanya untuk teks, radio hanya untuk angka", "Tidak ada perbedaan sama sekali"]$qa$::jsonb, 1, $qa$Radio (dengan name yang sama) membatasi satu pilihan; checkbox mengizinkan banyak pilihan.$qa$, 5) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
